mapper.sql:
SELECT T.ID, T.CATEGORY_ID, T.GOODS_SN, T.NAME, T.BRAND_ID, T.GOODS_NUMBER, T.KEYWORDS, T.GOODS_BRIEF, T.GOODS_DESC, T.IS_ON_SALE, T.ADD_TIME, T.SORT_ORDER, T.IS_DELETE, T.DELETE_TIME, T.ATTRIBUTE_CATEGORY, T.COUNTER_PRICE, T.EXTRA_PRICE, T.IS_NEW, T.GOODS_UNIT, T.PRIMARY_PIC_URL, T.LIST_PIC_URL, T.RETAIL_PRICE, T.SELL_VOLUME, T.PRIMARY_PRODUCT_ID, T.UNIT_PRICE, T.PROMOTION_DESC, T.PROMOTION_TAG, T.APP_EXCLUSIVE_PRICE, T.IS_APP_EXCLUSIVE, T.IS_LIMITED, T.IS_HOT, T.MARKET_PRICE, T.CREATE_USER_ID, T.UPDATE_USER_ID, T.UPDATE_TIME, T.CREATE_USER_DEPT_ID FROM mall_goods T WHERE T.IS_DELETE = 0
AND T.ID = #{params.id}
AND T.NAME LIKE CONCAT('%', #{params.name}, '%')
AND T.CATEGORY_ID = #{params.categoryId}

