mapper.select:
select a.id, a.name, a.list_pic_url, a.market_price, a.retail_price, a.goods_brief, b.id AS product_id,count(og.id) as order_num from mall_goods a left join mall_product b on a.id = b.goods_id left join mall_product c on a.id = c.goods_id and c.retail_price > b.retail_price and b.id != c.id left join mall_order_goods og on og.product_id = b.id
left join mall_goods_group gg on gg.goods_id = a.id
where 1 = 1 and b.id is not null and c.id is null and a.is_delete != 1
and a.is_new = #{isNew}
and a.is_hot = #{isHot}
and a.brand_id = #{brandId}
and a.name like concat('%',#{name},'%')
and a.category_id = #{categoryId}
and (a.keywords like concat('%',#{keyword},'%') or a.name like concat('%',#{keyword},'%'))
and gg.id is not null
and a.category_id in
#{item}
and a.id in
#{item}
group by a.id, a.name, a.list_pic_url, a.market_price, a.retail_price, a.goods_brief, b.id
order by a.retail_price
order by orderNum
order by a.id
asc
desc
limit #{offset}, #{limit}

